#!/usr/bin/env python3
"""Regenerates xtensaprograms.h (the unreal-xtensa test programs as a byte array plus symbol addresses).

Inputs next to this script: programs.S (hand-written tests, assembled with --no-transform so each mnemonic is encoded
as written), bench.c (compiled with -O2), and newlib's setjmp/longjmp object extracted from the toolchain's esp32s3
libc.a (the exact guest code ESP-IDF apps run).

Usage: genprograms.py --toolchain <dir with xtensa-esp32s3-elf-* tools> [--libc <esp32s3 libc.a>]
The ESP-IDF toolchain is the one used for the VDAC4 work (xtensa-esp-elf, GCC 16).
"""

import argparse
import os
import re
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(os.path.dirname(HERE), "xtensaprograms.h")

CODE_BASE = 0x40380000
TRAPS = {
    "TRAP_ADD2": 0x40000100,
    "TRAP_ADD8": 0x40000200,
    "TRAP_CB": 0x40000300,
    "TRAP_LEAF": 0x40000400,
}


def run(cmd, cwd=None):
    res = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if res.returncode != 0:
        sys.stderr.write(" ".join(cmd) + "\n" + res.stdout + res.stderr)
        sys.exit(1)
    return res.stdout


def pascal(name):
    return "".join(p[:1].upper() + p[1:] for p in re.split(r"[_.]", name) if p)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--toolchain", required=True, help="bin directory of the xtensa-esp-elf toolchain")
    ap.add_argument("--libc", help="esp32s3 newlib libc.a (default: <toolchain>/../xtensa-esp-elf/lib/esp32s3/libc.a)")
    args = ap.parse_args()
    tc = os.path.join(args.toolchain, "xtensa-esp32s3-elf-")
    libc = args.libc or os.path.join(args.toolchain, "..", "xtensa-esp-elf", "lib", "esp32s3", "libc.a")

    with tempfile.TemporaryDirectory() as tmp:
        run([tc + "as", "--no-transform", "--text-section-literals", "-o", os.path.join(tmp, "programs.o"),
             os.path.join(HERE, "programs.S")])
        run([tc + "gcc", "-O2", "-ffreestanding", "-fno-builtin", "-mtext-section-literals", "-c", "-o",
             os.path.join(tmp, "bench.o"), os.path.join(HERE, "bench.c")])
        run([tc + "ar", "x", os.path.abspath(libc), "libc_a-setjmp.o"], cwd=tmp)
        ld = [tc + "ld", "-o", os.path.join(tmp, "programs.elf"), "-Ttext=0x%x" % CODE_BASE, "-e", "alu",
              "--no-relax"]
        for name, addr in TRAPS.items():
            ld += ["--defsym", "%s=0x%x" % (name, addr)]
        ld += [os.path.join(tmp, f) for f in ("programs.o", "bench.o", "libc_a-setjmp.o")]
        run(ld)
        sections = run([tc + "objdump", "-h", os.path.join(tmp, "programs.elf")])
        for line in sections.splitlines():
            parts = line.split()
            if len(parts) > 2 and parts[1] in (".data", ".bss", ".rodata") and int(parts[2], 16) != 0:
                sys.exit("unexpected non-empty section " + parts[1])
        run([tc + "objcopy", "-O", "binary", "-j", ".text", os.path.join(tmp, "programs.elf"),
             os.path.join(tmp, "programs.bin")])
        code = open(os.path.join(tmp, "programs.bin"), "rb").read()
        symbols = {}
        for line in run([tc + "nm", os.path.join(tmp, "programs.elf")]).splitlines():
            parts = line.split()
            if len(parts) == 3 and parts[1] in "Tt" and not parts[2].startswith((".", "_")):
                symbols[parts[2]] = int(parts[0], 16)

    lines = [
        "// Generated by programs/genprograms.py from programs/programs.S, programs/bench.c and newlib's esp32s3",
        "// setjmp/longjmp. Do not edit: change the sources and re-run the script.",
        "",
        "#pragma once",
        "",
        "#include <cstdint>",
        "",
        "namespace XtensaPrograms",
        "{",
        "",
        "constexpr uint32_t kCodeBase = 0x%08X;" % CODE_BASE,
        "constexpr uint32_t kCodeSize = %d;" % len(code),
    ]
    for name, addr in TRAPS.items():
        lines.append("constexpr uint32_t k%s = 0x%08X;" % (pascal(name.lower()), addr))
    lines.append("")
    for name in sorted(symbols):
        lines.append("constexpr uint32_t k%s = 0x%08X;" % (pascal(name), symbols[name]))
    lines.append("")
    lines.append("// clang-format off")
    lines.append("inline constexpr uint8_t kCode[] = {")
    for i in range(0, len(code), 16):
        lines.append("    " + ", ".join("0x%02X" % b for b in code[i:i + 16]) + ",")
    lines.append("};")
    lines.append("// clang-format on")
    lines.append("")
    lines.append("} // namespace XtensaPrograms")
    open(OUT, "w").write("\n".join(lines) + "\n")
    print("wrote %s: %d bytes, %d symbols" % (OUT, len(code), len(symbols)))


if __name__ == "__main__":
    main()
